fs.mkdirSync('dist', {recursive:true});
for (const [name, contents] of Object.entries(files)) {
 if (!/^[a-zA-Z0-9_.-]+$/.test(name)) throw new Error('Unsafe filename');
 fs.writeFileSync('dist/'+name, Buffer.from(contents,'base64'));
}
const domain = process.env.VERCEL_PROJECT_PRODUCTION_URL || process.env.VERCEL_URL;
let html = fs.readFileSync('dist/index.html','utf8');
html=html.replace("500;600;700&family=Manrope:wght@500;600;700;800&display=swap');",'');
if(domain){
 const url = 'https://'+domain;
 html=html.replaceAll('content="./share.png"','content="'+url+'/share.png"');
 html=html.replace('</head>','<link rel="canonical" href="'+url+'/"><meta property="og:url" content="'+url+'/"></head>');
}
fs.writeFileSync('dist/index.html',html);
console.log('Built approved classroom with '+Object.keys(files).length+' files.');
